# interpreter/interpreter.py
# Executes the AST generated by the parser

class Interpreter:
    # executes LOLCode AST and manages runtime state
    
    def __init__(self, ast, symbol_table):
        self.ast = ast
        self.symbol_table = symbol_table
        self.output = []  # store VISIBLE output
        self.input_buffer = []  # for GIMMEH 
        self.functions = {} #for functio definitions
        self.execution_pointer = 0

        # create the implicit IT variable
        if "IT" not in self.symbol_table.symbols:
            self.symbol_table.symbols["IT"] = None
    

    def execute(self):
            if self.ast.type != 'program':
                raise RuntimeError("AST root must be a program node")
            executable_nodes = self.ast.children
            while self.execution_pointer < len(executable_nodes):
                node = executable_nodes[self.execution_pointer]
                result = self.execute_node(node)
                if isinstance(result, dict) and result.get('status') == 'awaiting_input':
                    return result

                self.execution_pointer += 1
            return {'status': 'completed', 'output': self.output}
        
    def execute_node(self, node):
        # execute a single AST node
        if node is None:
            return None
        node_type = node.type

        # variable declaration block
        if node_type == 'variable_declaration_block':
            for child in node.children:
                self.execute_node(child)
            return None

        # variable declaration (I HAS A)
        elif node_type == 'variable_declaration':
            var_name = node.value
            if node.children:
                # has initialization (ITZ)
                initial_value = self.evaluate_expression(node.children[0])
                self.symbol_table.symbols[var_name] = initial_value
            else:
                # no initialization set to NOOB
                self.symbol_table.symbols[var_name] = None
            return None
        
        # assignment statement
        elif node_type == 'assignment':
            var_name = node.value
            new_value = self.evaluate_expression(node.children[0])
            self.symbol_table.symbols[var_name] = new_value
            return None
        
        # print statement (VISIBLE)
        elif node_type == 'print_statement':
            output_parts = []
            for child in node.children:
                value = self.evaluate_expression(child)
                # convert to string for output
                output_parts.append(self.to_yarn(value))
            output_line = "".join(output_parts)
            # Check if newline should be suppressed (! at end)
            if hasattr(node, 'suppress_newline') and node.suppress_newline:
                # Append to last output line if exists, otherwise add new
                if self.output:
                    self.output[-1] = self.output[-1] + output_line
                else:
                    self.output.append(output_line)
            else:
                self.output.append(output_line)
            return None
        
       #executes  the switch block
        elif node_type == 'switch_statement':
            it_value = self.symbol_table.symbols.get("IT")

            case_executed = False #tracks if a matching case has been already run
            breaking = False #becomes true when GTFO meet

            #iterate through case/deaflut nodes
            for child in node.children:
                if child.type == 'case':
                    # literal in case
                    case_literal = child.value

                    if not case_executed and case_literal == it_value:
                        # execute satements inside case bloc
                        for stmt in child.children[1:]:
                            if stmt.type == "break": #GTFO ecnuntered
                                breaking = True
                                break
                            result = self.execute_node(stmt)
                            if isinstance(result, dict) and result.get('status') == 'awaiting_input':
                                return result
                            if isinstance(result, dict) and result.get('type') == 'break':
                                breaking = True
                                break
                        case_executed = True
                    
                    if breaking:
                        break #stop entirely
                elif child.type == 'default_case' and not case_executed:
                    for stmt in child.children:
                        result = self.execute_node(stmt)
                        if isinstance(result, dict) and result.get('status') == 'awaiting_input':
                            return result                    
                        if isinstance(result, dict) and result.get('type') == 'break':
                            break
                    break

            return None

        #GIMMEH
        elif node_type == 'input_statement':
            if not self.input_buffer:
                return {'status': 'awaiting_input', 'variable': node.value}
            user_input = self.input_buffer.pop(0)
            var_name = node.value
            self.symbol_table.symbols[var_name] = user_input
            return None 
        
        #IS NOW A: Hanndles type casting
        elif node_type == 'recast_statement':
            var_name = node.value
            target_type = node.children[0].value 
            current_value = self.symbol_table.symbols[var_name]
            new_value = self.perform_cast(current_value, target_type)
            self.symbol_table.symbols[var_name] = new_value
            self.symbol_table.symbols["IT"] = new_value
            return None

        #IM IN YR: Loop handling
        elif node_type == 'loop':
            return self.execute_loop(node)

        elif node_type == 'loop_statement': 
            setup = node.children[0]
            var_name = setup.value
            operation = setup.children[0].value
            # Loop until GTFO is called
            while True: 
                for stmt_node in node.children[1:]:
                    result = self.execute_node(stmt_node)
                    if result == 'break_loop':
                        return None
                
                current_val = self.to_number(self.symbol_table.symbols[var_name])
                if operation == 'UPPIN':
                    self.symbol_table.symbols[var_name] = current_val + 1
                else:
                    self.symbol_table.symbols[var_name] = current_val - 1
            return None

        elif node_type == 'break_statement': 
            return 'break_loop'

        #O RLY? / YA RLY / MEBBE / NO WAI
        elif node_type == 'orly_statement':
            # IT should already hold the condition
            it_value = self.symbol_table.symbols.get("IT", None)
            executed_block = False
            
            if self.to_troof(it_value):
                # Execute YA RLY block
                for child in node.children:
                    if child.type == 'ya_rly':
                        for stmt in child.children:
                            if stmt.type == 'break':
                                return {'type': 'break'}
                            result = self.execute_node(stmt)
                            if isinstance(result, dict):
                                if result.get('type') == 'break':
                                    return result
                                if result.get('status') == 'awaiting_input':
                                    return result
                        executed_block = True
                        break
            else:
                # Check MEBBE blocks (else if)
                for child in node.children:
                    if child.type == 'mebbe' and not executed_block:
                        # First child of mebbe is the condition expression
                        mebbe_condition = self.evaluate_expression(child.children[0])
                        if self.to_troof(mebbe_condition):
                            # Execute statements (skip first child which is condition)
                            for stmt in child.children[1:]:
                                if stmt.type == 'break':
                                    return {'type': 'break'}
                                result = self.execute_node(stmt)
                                if isinstance(result, dict):
                                    if result.get('type') == 'break':
                                        return result
                                    if result.get('status') == 'awaiting_input':
                                        return result
                            executed_block = True
                            break
                
                # Execute NO WAI block if exists and no block was executed
                if not executed_block:
                    for child in node.children:
                        if child.type == 'no_wai':
                            for stmt in child.children:
                                if stmt.type == 'break':
                                    return {'type': 'break'}
                                result = self.execute_node(stmt)
                                if isinstance(result, dict):
                                    if result.get('type') == 'break':
                                        return result
                                    if result.get('status') == 'awaiting_input':
                                        return result
                            break
            return None
        
        elif node_type == 'function_def':
            self.functions[node.value] = node
            return None

        elif node_type == 'function_call':
            return self.execute_function_call(node)

        elif node_type == 'return':
            value = self.evaluate_expression(node.children[0])
            return {"return": True, "value": value}

        elif node_type == 'expression_statement':
            result = self.evaluate_expression(node.children[0])
            self.symbol_table.symbols["IT"] = result
            return None

        elif node_type == 'break': 
            return "return_noob"
          
        else:
            result = self.evaluate_expression(node)
            self.symbol_table.symbols["IT"] = result
            return None
        
    # evaluates an expression node and returns its value
    def evaluate_expression(self, node):
        # evaluate an expression and return its value
        if node is None:
            return None
        
        node_type = node.type
        
        # Literals
        if node_type == 'literal_numbr':
            return int(node.value)
        
        elif node_type == 'literal_numbar':
            return float(node.value)
        
        elif node_type == 'literal_yarn':
            return str(node.value)
        
        elif node_type == 'literal_troof':
            # Handle both boolean (from tokenizer) and string (from parser)
            if isinstance(node.value, bool):
                return node.value
            return node.value == 'WIN'
        
        elif node_type == 'literal_noob':
            return None
        
        # Variable reference
        elif node_type == 'variable':
            var_name = node.value
            # check local scope
            if var_name not in self.symbol_table.symbols:
                raise RuntimeError(f"Variable '{var_name}' not declared")
            value = self.symbol_table.symbols[var_name]
            # Store in IT
            self.symbol_table.symbols["IT"] = value
            return value
        
        #MAEK
        elif node_type == 'maek_operation': 
            expr_to_cast = self.evaluate_expression(node.children[0])
            target_type = node.children[1].value
            result = self.perform_cast(expr_to_cast, target_type)
            self.symbol_table.symbols["IT"] = result
            return result

        #NOT evaluation
        elif node_type == 'unary_operation': 
            op = node.value
            operand = self.evaluate_expression(node.children[0])
            if op == 'NOT':
                return not self.to_troof(operand)
            else:
                raise RuntimeError(f"Unknown unary operation: {op}")

        elif node_type == 'variadic_operation':
            op = node.value
            operands = [self.evaluate_expression(child) for child in node.children]
            #SMOOSH
            if op == 'SMOOSH':
                return "".join([self.to_yarn(op_val) for op_val in operands])
            #ALL OF
            elif op == 'ALL OF':  
                return all(self.to_troof(op_val) for op_val in operands)
            #ANY OF
            elif op == 'ANY OF':
                return any(self.to_troof(op_val) for op_val in operands)
            else:
                raise RuntimeError(f"Unknown variadic operation: {op}")
            
        # Binary operations
        elif node_type == 'binary_operation':
            operation = node.value
            left = self.evaluate_expression(node.children[0])
            right = self.evaluate_expression(node.children[1])
            result = self.execute_binary_operation(operation, left, right)
            # Store result in IT
            self.symbol_table.symbols["IT"] = result
            return result
        
        # Function call as expression
        elif node_type == 'function_call':
            return self.execute_function_call(node)
        
        else:
            raise RuntimeError(f"Unknown expression type: {node_type}")
    
    def execute_binary_operation(self, operation, left, right):
        # execute a binary operation
        
        # Arithmetic operations
        if operation == 'SUM OF':
            left_num = self.to_number(left)
            right_num = self.to_number(right)
            result = left_num + right_num
            # return NUMBAR if either operand is NUMBAR, else NUMBR
            return result if isinstance(left_num, float) or isinstance(right_num, float) else int(result)
        
        elif operation == 'DIFF OF':
            left_num = self.to_number(left)
            right_num = self.to_number(right)
            result = left_num - right_num
            return result if isinstance(left_num, float) or isinstance(right_num, float) else int(result)
        
        elif operation == 'PRODUKT OF':
            left_num = self.to_number(left)
            right_num = self.to_number(right)
            result = left_num * right_num
            return result if isinstance(left_num, float) or isinstance(right_num, float) else int(result)
        
        elif operation == 'QUOSHUNT OF':
            left_num = self.to_number(left)
            right_num = self.to_number(right)
            if right_num == 0:
                raise RuntimeError("Division by zero")
            result = left_num / right_num
            return result if isinstance(left_num, float) or isinstance(right_num, float) else int(result)
        
        elif operation == 'MOD OF':
            left_num = self.to_number(left)
            right_num = self.to_number(right)
            if right_num == 0:
                raise RuntimeError("Modulo by zero")
            result = left_num % right_num
            return result if isinstance(left_num, float) or isinstance(right_num, float) else int(result)
        
        elif operation == 'BIGGR OF':
            left_num = self.to_number(left)
            right_num = self.to_number(right)
            result = max(left_num, right_num)
            return result if isinstance(left_num, float) or isinstance(right_num, float) else int(result)
        
        elif operation == 'SMALLR OF':
            left_num = self.to_number(left)
            right_num = self.to_number(right)
            result = min(left_num, right_num)
            return result if isinstance(left_num, float) or isinstance(right_num, float) else int(result)
        
        # Comparison operations
        elif operation == 'BOTH SAEM':
            # Try direct comparison first
            if left == right:
                return True
            # If one is string and other is number, try converting string to number
            if isinstance(left, str) and isinstance(right, (int, float)):
                try:
                    if '.' in left:
                        return float(left) == right
                    else:
                        return int(left) == right
                except ValueError:
                    return False
            if isinstance(right, str) and isinstance(left, (int, float)):
                try:
                    if '.' in right:
                        return left == float(right)
                    else:
                        return left == int(right)
                except ValueError:
                    return False
            return False
        
        elif operation == 'DIFFRINT':
            # Try direct comparison first
            if left == right:
                return False
            # If one is string and other is number, try converting string to number
            if isinstance(left, str) and isinstance(right, (int, float)):
                try:
                    if '.' in left:
                        return float(left) != right
                    else:
                        return int(left) != right
                except ValueError:
                    return True
            if isinstance(right, str) and isinstance(left, (int, float)):
                try:
                    if '.' in right:
                        return left != float(right)
                    else:
                        return left != int(right)
                except ValueError:
                    return True
            return True
        
        # Boolean operations
        elif operation == 'BOTH OF':
            return self.to_troof(left) and self.to_troof(right)
        
        elif operation == 'EITHER OF':
            return self.to_troof(left) or self.to_troof(right)
        
        elif operation == 'WON OF':
            return self.to_troof(left) != self.to_troof(right)
        
        else:
            raise RuntimeError(f"Unknown operation: {operation}")
    
    # Type casting
    def perform_cast(self, value, target_type):

        # NUMBR → integer
        if target_type == 'NUMBR':
            if value is None:
                return 0
            if isinstance(value, bool):
                return 1 if value else 0
            if isinstance(value, int):
                return value
            if isinstance(value, float):
                return int(value)
            if isinstance(value, str):
                if value.isdigit() or (value.startswith('-') and value[1:].isdigit()):
                    return int(value)
                raise RuntimeError(f"Cannot cast YARN '{value}' to NUMBR")
            raise RuntimeError(f"Cannot cast {type(value)} to NUMBR")

        # NUMBAR → float
        if target_type == 'NUMBAR':
            if value is None:
                return 0.0
            if isinstance(value, bool):
                return 1.0 if value else 0.0
            if isinstance(value, int) or isinstance(value, float):
                return float(value)
            if isinstance(value, str):
                try:
                    return float(value)
                except:
                    raise RuntimeError(f"Cannot cast YARN '{value}' to NUMBAR")
            raise RuntimeError(f"Cannot cast {type(value)} to NUMBAR")

        # YARN
        if target_type == 'YARN':
            if value is None:
                return ""
            return self.to_yarn(value)

        # TROOF
        if target_type == 'TROOF':
            return self.to_troof(value)

        # NOOB
        if target_type == 'NOOB':
            return None

        raise RuntimeError(f"Unknown type '{target_type}' in casting")


    # Type conversion helpers
    def to_number(self, value):
        # convert value to NUMBR or NUMBAR
        if value is None:
            raise RuntimeError("Cannot convert NOOB to number")
        
        if isinstance(value, bool):
            return 1 if value else 0
        
        if isinstance(value, int):
            return value
        
        if isinstance(value, float):
            return value
        
        if isinstance(value, str):
            # try to convert string to number
            try:
                if '.' in value:
                    return float(value)
                else:
                    return int(value)
            except ValueError:
                raise RuntimeError(f"Cannot convert '{value}' to number")
        
        raise RuntimeError(f"Cannot convert {type(value)} to number")
    
    def to_yarn(self, value):
        # convert value to YARN (string)
        if value is None:
            return "NOOB"
        
        if isinstance(value, bool):
            return "WIN" if value else "FAIL"
        
        if isinstance(value, float):
            s = str(value)
            if '.' in s:
                p = s.split('.')
                return p[0] + '.' + p[1][:2]
            return s
        
        return str(value)
    
    def to_troof(self, value):
        # convert value to TROOF (boolean)
        if value is None:
            return False
        
        if isinstance(value, bool):
            return value
        
        if isinstance(value, (int, float)):
            return value != 0
        
        if isinstance(value, str):
            return value != ""
        
        return True
    
    def execute_function_call(self, node):
        func_name = node.value
        if func_name not in self.functions:
            raise RuntimeError(f"Function '{func_name}' not defined")

        func_def = self.functions[func_name]

        # Evaluate arguments
        args = [self.evaluate_expression(child) for child in node.children]

        if len(args) != len(func_def.params):
            raise RuntimeError(f"Function '{func_name}' expects {len(func_def.params)} args, got {len(args)}")

        #create new local scope new sym table
        old_symbols = self.symbol_table.symbols.copy()
        # local scope with parent reference
        self.symbol_table.symbols = {}

        # Assign parameters
        for param, val in zip(func_def.params, args):
            self.symbol_table.symbols[param] = val

        # Execute body
        return_value = None
        for stmt in func_def.children:
            result = self.execute_node(stmt)

            # Return encountered
            if isinstance(result, dict) and result.get("return"):
                return_value = result["value"]
                break

            # GTFO without FOUND YR → NOOB return
            if result == "return_noob":
                return_value = None
                break

        # Restore previous scope
        self.symbol_table.symbols = old_symbols

        # Store return value in IT
        self.symbol_table.symbols["IT"] = return_value
        return return_value

    def execute_loop(self, node):
        # Execute a loop statement
        # node.value contains the loop label
        # Children: loop_operation (optional), loop_condition (optional), loop_body

        operation_node = None
        condition_node = None
        body_node = None

        # Extract child nodes
        for child in node.children:
            if child.type == 'loop_operation':
                operation_node = child
            elif child.type == 'loop_condition':
                condition_node = child
            elif child.type == 'loop_body':
                body_node = child

        # Infinite loop protection counter
        max_iterations = 10000
        iteration_count = 0

        while True:
            iteration_count += 1
            if iteration_count > max_iterations:
                raise RuntimeError(f"Loop exceeded maximum iterations ({max_iterations})")

            # Check condition before loop body (for TIL and WILE)
            if condition_node:
                condition_type = condition_node.value
                condition_expr = condition_node.children[0]
                condition_value = self.evaluate_expression(condition_expr)
                condition_bool = self.to_troof(condition_value)

                # TIL: loop until condition is true (while false)
                # WILE: loop while condition is true
                if condition_type == 'TIL':
                    if condition_bool:  # Condition is true, exit loop
                        break
                elif condition_type == 'WILE':
                    if not condition_bool:  # Condition is false, exit loop
                        break

            # Execute loop body
            if body_node:
                should_break = False
                for stmt in body_node.children:
                    if stmt.type == 'break':
                        should_break = True
                        break
                    result = self.execute_node(stmt)
                    if isinstance(result, dict) and result.get('type') == 'break':
                        should_break = True
                        break
                if should_break:
                    break

            # Perform operation (UPPIN or NERFIN) after body
            if operation_node:
                op_info = operation_node.value
                operation = op_info['operation']
                var_name = op_info['variable']

                # Get current value
                if var_name not in self.symbol_table.symbols:
                    raise RuntimeError(f"Loop variable '{var_name}' not declared")

                current_value = self.symbol_table.symbols[var_name]

                # Convert to number if needed
                if current_value is None:
                    current_value = 0
                else:
                    current_value = self.to_number(current_value)

                # Increment or decrement
                if operation == 'UPPIN':
                    new_value = current_value + 1
                elif operation == 'NERFIN':
                    new_value = current_value - 1

                # Update variable
                self.symbol_table.symbols[var_name] = new_value

        return None